const B = new Builder();

/* =========================================================================
   PROCEDURAL TEXTURES
   ========================================================================= */
const MAX_ANISO = Math.min(8, renderer.capabilities.getMaxAnisotropy());
function newCanvas(size) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  return c;
}
function tex(c, srgb = true, rep = 1) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(rep, rep);
  t.anisotropy = MAX_ANISO;
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  t.needsUpdate = true;
  return t;
}
function hash2i(x, y, s) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(s | 0, 1274126177);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}
function vnoiseP(x, y, period, s) {
  const xi = Math.floor(x), yi = Math.floor(y);
  const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const x0 = ((xi % period) + period) % period, y0 = ((yi % period) + period) % period;
  const x1 = (x0 + 1) % period, y1 = (y0 + 1) % period;
  return lerp(lerp(hash2i(x0, y0, s), hash2i(x1, y0, s), u),
              lerp(hash2i(x0, y1, s), hash2i(x1, y1, s), u), v);
}
function fbmP(x, y, period, oct, s) {
  let sum = 0, amp = 0.5, norm = 0, p = period;
  for (let i = 0; i < oct; i++) {
    sum += amp * vnoiseP(x, y, p, s + i * 37);
    norm += amp; x *= 2; y *= 2; p *= 2; amp *= 0.5;
