    let r = lerp(92, 142, rust) + (f - 0.5) * 18;
    let g = lerp(78, 74, rust) + (f - 0.5) * 12;
    let b = lerp(64, 44, rust) + (f - 0.5) * 8;
    const dark = Math.max(0, fbmP(x / 100 + 5, y / 100, 5, 3, 409) - 0.62) * 120;
