function facadeTexture(seed, base, glass) {
  const c = newCanvas(512), ctx = c.getContext('2d');
  ctx.fillStyle = base; ctx.fillRect(0, 0, 512, 512);
  for (let i = 0; i < 5000; i++) {
    ctx.fillStyle = `rgba(255,255,255,${rnd(0.01, 0.05)})`;
    ctx.fillRect(rnd(0, 512), rnd(0, 512), rnd(1, 3), rnd(1, 3));
  }
  const cols = 6, rows = 6;
  for (let r = 0; r < rows; r++) for (let k = 0; k < cols; k++) {
    const x = 24 + k * 80, y = 22 + r * 82, w = 42, h = 54;
    ctx.fillStyle = 'rgba(28,30,31,.95)'; ctx.fillRect(x - 4, y - 4, w + 8, h + 8);
    const lit = hash2i(k + seed, r, 7) > 0.82;
    ctx.fillStyle = lit ? 'rgba(255,196,120,.7)' : glass;
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = 'rgba(255,255,255,.08)'; ctx.fillRect(x, y, w, 2);
    ctx.fillStyle = 'rgba(30,30,30,.8)'; ctx.fillRect(x + w / 2 - 1, y, 2, h);
    ctx.fillStyle = 'rgba(200,195,180,.35)'; ctx.fillRect(x - 5, y + h + 3, w + 10, 3);
  }
  for (let i = 0; i < 10; i++) stain(ctx, rnd(0, 512), rnd(0, 512), rnd(20, 80), '20,18,14', rnd(0.05, 0.16));
  return tex(c);
}
