/* ---------- sign / poster / graffiti canvases ---------- */
function signTexture(text, sub, bg, fg, accent) {
  const w = 512, h = 128;
  const c = document.createElement('canvas'); c.width = w; c.height = h;
  const ctx = c.getContext('2d');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = 'rgba(0,0,0,.35)'; ctx.lineWidth = 6; ctx.strokeRect(3, 3, w - 6, h - 6);
  ctx.fillStyle = accent; ctx.fillRect(0, 0, 14, h);
  ctx.fillStyle = fg; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '900 56px "Arial Narrow", Impact, sans-serif';
  ctx.fillText(text, w / 2 + 8, sub ? h / 2 - 14 : h / 2, w - 60);
  if (sub) {
    ctx.font = '600 20px "Arial Narrow", sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,.55)';
    ctx.fillText(sub, w / 2 + 8, h / 2 + 32, w - 80);
  }
  for (let i = 0; i < 70; i++) {
    ctx.fillStyle = `rgba(0,0,0,${rnd(0.03, 0.14)})`;
    ctx.fillRect(rnd(0, w), rnd(0, h), rnd(1, 9), rnd(1, 2));
  }
  for (let i = 0; i < 5; i++) stain(ctx, rnd(0, w), rnd(0, h), rnd(8, 40), '0,0,0', rnd(0.05, 0.16));
  const t = tex(c);
  t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
  return t;
}
