/* ---------- bullet impact decals ---------- */
function decalTexture(type) {
  const c = newCanvas(256), ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 256, 256);
  const cx = 128, cy = 128;
  if (type === 'glass') {
    ctx.strokeStyle = 'rgba(225,240,245,.8)'; ctx.lineWidth = 1.4;
    for (let i = 0; i < 16; i++) {
      const a = rnd(0, TAU); let x = cx, y = cy;
      ctx.beginPath(); ctx.moveTo(cx, cy);
      for (let k = 0; k < 5; k++) { x += Math.cos(a + rnd(-0.2, 0.2)) * rnd(8, 22); y += Math.sin(a + rnd(-0.2, 0.2)) * rnd(8, 22); ctx.lineTo(x, y); }
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(20,28,30,.8)'; ctx.beginPath(); ctx.arc(cx, cy, 8, 0, TAU); ctx.fill();
    return tex(c);
  }
  const hole = type === 'metal' ? 10 : 14;
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, 34);
  g.addColorStop(0, 'rgba(6,6,6,.98)');
  g.addColorStop(0.3, 'rgba(18,17,16,.95)');
  g.addColorStop(0.55, 'rgba(40,38,35,.55)');
  g.addColorStop(1, 'rgba(60,55,50,0)');
  ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, 34, 0, TAU); ctx.fill();
  ctx.fillStyle = 'rgba(8,8,8,1)'; ctx.beginPath(); ctx.arc(cx, cy, hole, 0, TAU); ctx.fill();
  if (type === 'metal') {
    ctx.strokeStyle = 'rgba(230,220,200,.7)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(cx, cy, hole + 2, 0, TAU); ctx.stroke();
    ctx.strokeStyle = 'rgba(190,180,160,.35)'; ctx.lineWidth = 1;
    for (let i = 0; i < 10; i++) {
      const a = rnd(0, TAU);
      ctx.beginPath(); ctx.moveTo(cx + Math.cos(a) * 12, cy + Math.sin(a) * 12);
      ctx.lineTo(cx + Math.cos(a) * rnd(25, 60), cy + Math.sin(a) * rnd(25, 60)); ctx.stroke();
    }
  } else {
    ctx.strokeStyle = type === 'wood' ? 'rgba(110,80,45,.6)' : 'rgba(190,180,165,.4)';
    ctx.lineWidth = 1.3;
    for (let i = 0; i < 9; i++) {
      const a = rnd(0, TAU);
      ctx.beginPath(); ctx.moveTo(cx, cy);
      let x = cx, y = cy;
      for (let k = 0; k < 4; k++) { x += Math.cos(a + rnd(-0.3, 0.3)) * rnd(5, 15); y += Math.sin(a + rnd(-0.3, 0.3)) * rnd(5, 15); ctx.lineTo(x, y); }
      ctx.stroke();
    }
    if (type === 'brick') {
      ctx.fillStyle = 'rgba(120,60,42,.6)';
      for (let i = 0; i < 12; i++) { ctx.beginPath(); ctx.arc(cx + rnd(-30, 30), cy + rnd(-30, 30), rnd(1, 3), 0, TAU); ctx.fill(); }
    }
  }
  return tex(c);
}
