/* ---------- sprites ---------- */
function radialSprite(size, inner, outer, power = 1) {
  const c = newCanvas(size), ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner); g.addColorStop(0.35, inner);
  g.addColorStop(0.7, outer); g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, size, size);
  return tex(c);
