  const topY = floorY + steps * rise;
  const topZ = zTop + dir * steps * run;
  B.box(width + 0.2, 0.18, 1.2, x, topY - 0.09, topZ + dir * 0.5, 'concrete', { uv: 0.6, collide: true });
