  const ry = Math.atan2(x1 - x0, z1 - z0);
  const cx = (x0 + x1) / 2, cz = (z0 + z1) / 2;
  B.box(0.05, 0.05, len, cx, y + height, cz, mat, { ry });
  B.box(0.04, 0.04, len, cx, y + height * 0.55, cz, mat, { ry });
  const n = Math.max(2, Math.round(len / 0.55));
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    B.box(0.035, height, 0.035, lerp(x0, x1, t), y + height / 2, lerp(z0, z1, t), mat, {});
