  const curve = new THREE.CatmullRomCurve3(pts);
  const g = new THREE.TubeGeometry(curve, 20, 0.022, 4, false);
  B.add(g, 'cable', new THREE.Matrix4());
}

/* wall builders with real openings */
function wallX(z, x0, x1, y0, y1, thick, mat, openings = []) {
  const sorted = [...openings].sort((a, b) => a.x0 - b.x0);
  let cursor = x0;
  for (const o of sorted) {
    if (o.x0 > cursor) B.box(o.x0 - cursor, y1 - y0, thick, (cursor + o.x0) / 2, (y0 + y1) / 2, z, mat, { uv: 0.42, collide: true });
    if (o.y0 > y0) B.box(o.x1 - o.x0, o.y0 - y0, thick, (o.x0 + o.x1) / 2, (y0 + o.y0) / 2, z, mat, { uv: 0.42, collide: true });
    if (o.y1 < y1) B.box(o.x1 - o.x0, y1 - o.y1, thick, (o.x0 + o.x1) / 2, (o.y1 + y1) / 2, z, mat, { uv: 0.42, collide: true });
    cursor = Math.max(cursor, o.x1);
  }
  if (cursor < x1) B.box(x1 - cursor, y1 - y0, thick, (cursor + x1) / 2, (y0 + y1) / 2, z, mat, { uv: 0.42, collide: true });
}
function wallZ(x, z0, z1, y0, y1, thick, mat, openings = []) {
  const sorted = [...openings].sort((a, b) => a.z0 - b.z0);
  let cursor = z0;
  for (const o of sorted) {
    if (o.z0 > cursor) B.box(thick, y1 - y0, o.z0 - cursor, x, (y0 + y1) / 2, (cursor + o.z0) / 2, mat, { uv: 0.42, collide: true });
    if (o.y0 > y0) B.box(thick, o.y0 - y0, o.z1 - o.z0, x, (y0 + o.y0) / 2, (o.z0 + o.z1) / 2, mat, { uv: 0.42, collide: true });
    if (o.y1 < y1) B.box(thick, y1 - o.y1, o.z1 - o.z0, x, (o.y1 + y1) / 2, (o.z0 + o.z1) / 2, mat, { uv: 0.42, collide: true });
    cursor = Math.max(cursor, o.z1);
  }
  if (cursor < z1) B.box(thick, y1 - y0, z1 - cursor, x, (y0 + y1) / 2, (cursor + z1) / 2, mat, { uv: 0.42, collide: true });
}

