function addSofa(x, z, ry, mat = 'fabricBlue') {
  const base = M4(x, 0.16, z, 0, ry);
  localAdd(base, new THREE.BoxGeometry(2.2, 0.34, 0.9), mat, 0, 0.25, 0);
  localAdd(base, new THREE.BoxGeometry(2.1, 0.22, 0.78), mat, 0, 0.47, 0.02);
