  for (const s of [-1, 1]) localAdd(base, new THREE.BoxGeometry(0.85, 0.16, 0.68), 'fabricTan', s * 0.52, 0.57, 0.06);
  for (const sx of [-0.9, 0.9]) for (const sz of [-0.3, 0.3]) localAdd(base, new THREE.BoxGeometry(0.07, 0.14, 0.07), 'metalDark', sx, 0.07, sz);
  addCollider(x, z, 1.15, 0.52, 0.16, 1.0, 'sofa');
}
function addTV(x, y, z, ry) {
  const base = M4(x, y, z, 0, ry);
  localAdd(base, new THREE.BoxGeometry(1.2, 0.45, 0.4), 'wood', 0, 0.22, 0);
  localAdd(base, new THREE.BoxGeometry(1.05, 0.62, 0.07), 'blackPaint', 0, 0.78, 0);
  localAdd(base, new THREE.PlaneGeometry(0.96, 0.53), 'windowDark', 0, 0.78, 0.04);
  localAdd(base, new THREE.BoxGeometry(0.05, 0.05, 0.05), 'blackPaint', 0, 0.43, 0);
  addCollider(x, z, 0.62, 0.25, y, y + 1.1, 'tv');
