function addShelf(x, y, z, ry, w = 1.4, h = 1.9, d = 0.34) {
  const base = M4(x, y, z, 0, ry);
  for (const s of [-1, 1]) localAdd(base, new THREE.BoxGeometry(0.05, h, d), 'wood', s * (w / 2 - 0.03), h / 2, 0);
