  .controls kbd{font-family:var(--mono);font-size:10px;color:var(--accent);letter-spacing:.06em}
  .controls span{font-size:9px;letter-spacing:.18em;color:#8e908b;text-transform:uppercase}
  .footnote{position:absolute;right:52px;bottom:22px;font-size:8px;letter-spacing:.24em;color:#5f615e;text-transform:uppercase}

  #loading{position:fixed;inset:0;z-index:80;display:flex;flex-direction:column;align-items:center;justify-content:center;
    background:#07080a;transition:opacity .5s;gap:20px}
  #loading.hidden{opacity:0;pointer-events:none}
  #loading .lbl{font-size:10px;letter-spacing:.5em;color:var(--accent);text-transform:uppercase}
  #loading .bar{width:260px;height:2px;background:rgba(255,255,255,.1);overflow:hidden}
  #loading .bar i{display:block;height:100%;width:0%;background:var(--accent);transition:width .2s}
  #loading .pct{font-family:var(--mono);font-size:9px;color:#6c6e6a;letter-spacing:.1em}

  #pause .panel{width:min(520px,90vw);text-align:center}
  #pause h2{font-size:46px;letter-spacing:.06em;text-transform:uppercase;font-weight:900;color:#eeeae1}
  #pause .sub{margin-bottom:28px}
  #pause .controls{grid-template-columns:repeat(3,1fr)}

  #debug{position:fixed;left:8px;bottom:8px;z-index:70;font-family:var(--mono);font-size:10px;
    color:#8fdc9b;background:rgba(0,0,0,.55);padding:6px 9px;display:none;white-space:pre;line-height:1.5}
  #debug.on{display:block}
  #errorbox{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:99;display:none;
    max-width:80vw;background:#210c0c;border:1px solid #a33;padding:20px;font-family:var(--mono);font-size:12px;color:#ffb4a8}
  @media (max-width:760px){
    .panel{padding:30px 24px}
    .controls{grid-template-columns:repeat(2,1fr)}
    .brief{display:none}
    .top-left{top:16px;left:16px}
    .bottom-right{right:16px;bottom:16px}
    .bottom-left{left:16px;bottom:16px}
    .footnote{display:none}
  }
