    <div class="firemode" id="firemode">AUTO · 600 RPM</div>
    <div class="reloadbar" id="reloadbar"><i></i></div>
  </div>
  <div class="bottom-left">
    <div class="stance" id="stance">STANDING</div>
    <div class="targets">STEEL TARGETS <b id="score">0</b></div>
  </div>
  <div class="hint" id="hint">ESC RELEASES CURSOR · R RELOAD · F INSPECT</div>
  <div class="vignette"></div>
  <div class="grain"></div>
</div>

<div id="start" class="overlay">
  <div class="panel">
    <div class="eyebrow">STAGE 01 / URBAN COMBAT PROTOTYPE</div>
    <h1>GREY<span>ZONE</span></h1>
    <div class="sub">SECTOR 07 — DOWNTOWN — 18:42 LOCAL</div>
    <p class="brief"><b>Brief:</b> The block went dark four hours ago. Move through Meridian Street,
      clear the café, the tenement and the loading depot. Hostiles are not yet simulated in this
      stage — the block is live, the weapon is live. Use the steel to get your zero.</p>
    <div class="startrow">
      <button id="startBtn" aria-label="start">START</button>
      <div class="clicknote">Headphones recommended · Desktop · Mouse + keyboard</div>
    </div>
    <div class="controls">
      <div><kbd>W A S D</kbd><span>Move</span></div>
      <div><kbd>SHIFT</kbd><span>Sprint</span></div>
      <div><kbd>C</kbd><span>Crouch</span></div>
      <div><kbd>SPACE</kbd><span>Jump</span></div>
      <div><kbd>MOUSE L</kbd><span>Fire</span></div>
      <div><kbd>MOUSE R</kbd><span>Aim down sights</span></div>
      <div><kbd>R</kbd><span>Reload</span></div>
      <div><kbd>F</kbd><span>Inspect weapon</span></div>
      <div><kbd>ESC</kbd><span>Release cursor</span></div>
      <div><kbd>F3</kbd><span>Performance</span></div>
      <div><kbd>M</kbd><span>Mute</span></div>
      <div><kbd>E</kbd><span>Interact</span></div>
    </div>
    <div class="footnote">Procedural build · Three.js · No external assets</div>
  </div>
</div>

<div id="pause" class="overlay hidden">
  <div class="panel">
    <div class="eyebrow">TACTICAL PAUSE</div>
    <h2>HOLDING</h2>
    <div class="sub">CURSOR RELEASED — CLICK BELOW TO RESUME</div>
    <div class="startrow" style="justify-content:center">
      <button id="resumeBtn" aria-label="play">RESUME</button>
    </div>
    <div class="controls">
      <div><kbd>MOUSE L</kbd><span>Fire</span></div>
      <div><kbd>MOUSE R</kbd><span>Aim</span></div>
      <div><kbd>R</kbd><span>Reload</span></div>
    </div>
  </div>
</div>

