  .stance{color:#dcd9cf}
  .stance:before{content:"";display:inline-block;width:7px;height:7px;border:1px solid var(--accent);
    transform:rotate(45deg);margin-right:9px;vertical-align:1px}
  .targets b{color:var(--accent);font-family:var(--mono);font-size:12px}
  .hint{position:absolute;left:50%;bottom:22px;transform:translateX(-50%);font-size:9px;letter-spacing:.28em;
    color:rgba(255,255,255,.32);text-transform:uppercase;transition:opacity 1s}
  .hint.gone{opacity:0}

  /* ---------- overlays ---------- */
  .overlay{position:fixed;inset:0;z-index:40;display:flex;align-items:center;justify-content:center;
    background:radial-gradient(ellipse at 50% 35%, rgba(22,25,26,.72), rgba(4,5,6,.94) 72%);
    backdrop-filter:blur(9px) saturate(.8);-webkit-backdrop-filter:blur(9px) saturate(.8);
    transition:opacity .45s ease, visibility .45s}
  .overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
  .overlay:before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.5;
    background-image:linear-gradient(rgba(255,255,255,.028) 1px, transparent 1px),
                     linear-gradient(90deg, rgba(255,255,255,.028) 1px, transparent 1px);
    background-size:64px 64px;mask-image:radial-gradient(ellipse at center, black, transparent 75%)}
  .panel{position:relative;width:min(880px,92vw);padding:44px 52px 38px;
    border:1px solid rgba(255,255,255,.12);background:linear-gradient(160deg, rgba(16,18,19,.88), rgba(8,9,10,.92));
    box-shadow:0 30px 100px rgba(0,0,0,.75), inset 0 1px 0 rgba(255,255,255,.06)}
  .panel:after{content:"";position:absolute;top:0;left:0;width:64px;height:3px;background:var(--accent)}
  .eyebrow{font-size:10px;letter-spacing:.42em;color:var(--accent);text-transform:uppercase;margin-bottom:16px}
  h1{font-family:var(--cond);font-size:clamp(58px,10vw,108px);line-height:.82;letter-spacing:.02em;
    font-weight:900;text-transform:uppercase;color:#f1eee5;text-shadow:0 8px 40px rgba(0,0,0,.6)}
  h1 span{color:var(--accent);display:inline-block;margin-left:.1em;font-style:italic}
  .sub{margin-top:14px;font-size:11px;letter-spacing:.38em;color:#a8a69e;text-transform:uppercase}
  .brief{max-width:560px;margin-top:24px;font-family:var(--mono);font-size:11.5px;line-height:1.75;
    color:#9e9f9a;letter-spacing:.01em;border-left:1px solid rgba(255,122,42,.5);padding-left:16px}
  .brief b{color:#ddd9cf;font-weight:500}
  .startrow{display:flex;align-items:center;gap:24px;margin-top:30px;flex-wrap:wrap}
  button{font-family:var(--cond);cursor:pointer;border:1px solid var(--accent);color:#0b0c0d;
    background:var(--accent);font-size:14px;font-weight:800;letter-spacing:.26em;text-transform:uppercase;
    padding:15px 36px;position:relative;transition:background .18s,color .18s,transform .18s,box-shadow .18s;
    clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%)}
  button:hover{background:#ff8e4d;box-shadow:0 0 34px rgba(255,122,42,.28);transform:translateY(-1px)}
  button:active{transform:translateY(1px)}
  button.ghost{background:transparent;color:#d7d4ca;border-color:rgba(255,255,255,.25)}
  button.ghost:hover{background:rgba(255,255,255,.06);box-shadow:none}
  .clicknote{font-size:9px;letter-spacing:.3em;color:#6f716d;text-transform:uppercase}
  .controls{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;margin-top:34px;
    background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.07)}
  .controls div{background:rgba(8,9,10,.86);padding:11px 13px;display:flex;flex-direction:column;gap:5px}
  .controls kbd{font-family:var(--mono);font-size:10px;color:var(--accent);letter-spacing:.06em}
  .controls span{font-size:9px;letter-spacing:.18em;color:#8e908b;text-transform:uppercase}
  .footnote{position:absolute;right:52px;bottom:22px;font-size:8px;letter-spacing:.24em;color:#5f615e;text-transform:uppercase}

