/* =========================================================================
   PROP HELPERS — crates, barrels, street furniture, parked vehicles
   ========================================================================= */
MATS.coneOrange = std({ color: 0xb84a1e, roughness: 0.82 });
MATS.brass = std({ color: 0xb08a42, roughness: 0.32, metalness: 0.92, envMapIntensity: 1.2 });

function addCrate(x, y, z, s = 1, ry = 0, mat = 'plank') {
  const base = M4(x, y, z, 0, ry);
  const r = Math.min(0.035, s * 0.055);
  localAdd(base, new RoundedBoxGeometry(s, s, s, 2, r), mat, 0, s / 2, 0);
  for (const sx of [-1, 1]) for (const sz of [-1, 1])
    localAdd(base, new THREE.BoxGeometry(0.055, s * 0.97, 0.055), 'wood', sx * (s / 2 - 0.034), s / 2, sz * (s / 2 - 0.034));
  for (const sy of [0.16, 0.5, 0.84]) {
    localAdd(base, new THREE.BoxGeometry(s * 0.98, 0.042, 0.045), 'wood', 0, s * sy, s / 2 + 0.002);
    localAdd(base, new THREE.BoxGeometry(s * 0.98, 0.042, 0.045), 'wood', 0, s * sy, -s / 2 - 0.002);
    localAdd(base, new THREE.BoxGeometry(0.045, 0.042, s * 0.98), 'wood', s / 2 + 0.002, s * sy, 0);
    localAdd(base, new THREE.BoxGeometry(0.045, 0.042, s * 0.98), 'wood', -s / 2 - 0.002, s * sy, 0);
  }
  addColliderRot(x, z, s / 2, s / 2, ry, y, y + s, 'crate');
}

function addBarrel(x, z, ry = 0, y = 0.16, open = false) {
  const base = M4(x, y, z, 0, ry);
  localAdd(base, new THREE.CylinderGeometry(0.28, 0.28, 0.88, 16), 'rustDark', 0, 0.44, 0);
  for (const yy of [0.16, 0.44, 0.72])
    localAdd(base, new THREE.CylinderGeometry(0.293, 0.293, 0.045, 16), 'metalDark', 0, yy, 0);
  localAdd(base, new THREE.CylinderGeometry(0.283, 0.283, 0.025, 16), open ? 'blackPaint' : 'metalDark', 0, 0.895, 0);
  if (open) localAdd(base, new THREE.CylinderGeometry(0.235, 0.235, 0.012, 16), 'blackPaint', 0, 0.872, 0);
  else {
    localAdd(base, new THREE.CylinderGeometry(0.055, 0.055, 0.02, 10), 'metalDark', 0.13, 0.91, 0.04);
  }
  addColliderRot(x, z, 0.29, 0.29, ry, y, y + 0.9, 'barrel');
}

function addDumpster(x, z, ry = 0) {
  const base = M4(x, 0.16, z, 0, ry);
  localAdd(base, new RoundedBoxGeometry(2.0, 1.02, 1.15, 2, 0.05), 'metalPainted', 0, 0.66, 0);
  localAdd(base, new THREE.BoxGeometry(2.02, 0.12, 1.17), 'metalDark', 0, 1.2, 0);
  localAdd(base, new THREE.BoxGeometry(1.9, 0.09, 0.78), 'metalPainted', 0, 1.28, -0.14, -0.13, 0, 0);
  localAdd(base, new THREE.BoxGeometry(1.9, 0.09, 0.78), 'metalPainted', 0, 1.28, 0.14, 0.13, 0, 0);
  for (const sx of [-0.86, 0.86]) for (const sz of [-0.46, 0.46])
    localAdd(base, new THREE.CylinderGeometry(0.13, 0.13, 0.1, 10), 'rubber', sx, 0.11, sz, 0, 0, Math.PI / 2);
  for (const sx of [-0.72, 0, 0.72])
    localAdd(base, new THREE.BoxGeometry(0.06, 0.78, 0.02), 'metalDark', sx, 0.66, 0.585);
  localAdd(base, new THREE.BoxGeometry(1.5, 0.1, 0.04), 'yellowPaint', 0, 0.82, 0.585);
  addColliderRot(x, z, 1.03, 0.61, ry, 0.16, 1.46, 'dumpster');
}

function addBench(x, z, ry = 0) {
  const base = M4(x, 0.16, z, 0, ry);
  localAdd(base, new THREE.BoxGeometry(1.85, 0.08, 0.48), 'wood', 0, 0.46, 0);
  localAdd(base, new THREE.BoxGeometry(1.85, 0.42, 0.06), 'wood', 0, 0.74, -0.23, -0.08, 0, 0);
  for (const sx of [-0.74, 0.74]) {
    localAdd(base, new THREE.BoxGeometry(0.07, 0.46, 0.07), 'metalDark', sx, 0.23, 0.15);
    localAdd(base, new THREE.BoxGeometry(0.07, 0.76, 0.07), 'metalDark', sx, 0.38, -0.2);
    localAdd(base, new THREE.BoxGeometry(0.07, 0.06, 0.5), 'metalDark', sx, 0.02, 0);
  }
  addColliderRot(x, z, 0.95, 0.3, ry, 0.16, 0.96, 'bench');
}

function addTrashCan(x, z) {
  B.cyl(0.31, 0.27, 0.82, 14, x, 0.57, z, 'metalDark', { collide: true });
  B.cyl(0.33, 0.33, 0.06, 14, x, 1.0, z, 'metalDark', {});
  B.cyl(0.12, 0.12, 0.04, 10, x, 1.05, z, 'blackPaint', {});
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * TAU;
    B.box(0.025, 0.62, 0.02, x + Math.cos(a) * 0.29, 0.57, z + Math.sin(a) * 0.29, 'blackPaint', { ry: -a });
  }
}

function addVending(x, z, ry = 0) {
  const base = M4(x, 0.16, z, 0, ry);
  localAdd(base, new RoundedBoxGeometry(1.0, 1.9, 0.72, 2, 0.035), 'paintRed', 0, 0.95, 0);
  localAdd(base, new THREE.BoxGeometry(0.82, 1.18, 0.03), 'windowDark', 0, 1.18, 0.36);
  localAdd(base, new THREE.BoxGeometry(0.74, 1.05, 0.012), 'lampCool', 0, 1.18, 0.377);
  for (let r = 0; r < 4; r++) for (let c = 0; c < 4; c++)
    localAdd(base, new THREE.BoxGeometry(0.11, 0.15, 0.03), pick(['targetRed', 'fabricGreen', 'steelBlue', 'cardboard']), -0.26 + c * 0.17, 0.72 + r * 0.26, 0.39);
  localAdd(base, new THREE.BoxGeometry(0.72, 0.22, 0.04), 'metalDark', 0, 0.38, 0.37);
  localAdd(base, new THREE.BoxGeometry(0.3, 0.08, 0.03), 'fluorescent', 0.22, 1.74, 0.37);
  addColliderRot(x, z, 0.52, 0.38, ry, 0.16, 2.06, 'vending');
}

function addPallet(x, z, ry = 0, y = 0.16) {
  const base = M4(x, y, z, 0, ry);
  for (const sz of [-0.42, 0, 0.42]) localAdd(base, new THREE.BoxGeometry(1.2, 0.11, 0.12), 'plank', 0, 0.06, sz);
  for (let i = 0; i < 6; i++) localAdd(base, new THREE.BoxGeometry(0.16, 0.035, 1.0), 'plank', -0.52 + i * 0.208, 0.135, 0);
  for (const sx of [-0.5, 0, 0.5]) localAdd(base, new THREE.BoxGeometry(0.1, 0.09, 1.0), 'wood', sx, 0.02, 0);
}

function addTire(x, z, ry = 0, y = 0.16) {
  B.add(new THREE.TorusGeometry(0.31, 0.115, 8, 18), 'tire', M4(x, y + 0.12, z, Math.PI / 2, ry, 0));
  B.add(new THREE.CylinderGeometry(0.19, 0.19, 0.02, 12), 'rustDark', M4(x, y + 0.12, z, Math.PI / 2, ry, 0));
}

function addCar(x, z, ry = 0, paint = 'paintBlue', kind = 'sedan') {
  const van = kind === 'van';
  const L = van ? 5.0 : 4.35, W = van ? 2.02 : 1.82;
  const base = M4(x, 0, z, 0, ry);
  if (van) {
    localAdd(base, new RoundedBoxGeometry(W, 1.55, L, 2, 0.12), paint, 0, 1.05, 0.1);
    localAdd(base, new RoundedBoxGeometry(W * 0.94, 0.72, 1.5, 2, 0.1), paint, 0, 1.0, -L / 2 + 0.78);
    localAdd(base, new THREE.BoxGeometry(W * 0.82, 0.48, 0.04), 'glassDark', 0, 1.24, -L / 2 + 0.02);
    for (const s of [-1, 1]) localAdd(base, new THREE.BoxGeometry(0.04, 0.42, 0.9), 'glassDark', s * W * 0.47, 1.25, -L / 2 + 0.84);
    localAdd(base, new THREE.BoxGeometry(W * 0.86, 0.06, L * 0.8), paint, 0, 1.84, 0.12);
