      transparent: true,
      depthWrite: false,
      depthTest: true,
      blending,
    });
    this.points = new THREE.Points(this.geo, this.mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 4;
    scene.add(this.points);
  }
  spawn(x, y, z, vx, vy, vz, r, g, b, size, life, gravity = 9.8, drag = 0.985) {
    if (this.items.length >= this.max) return;
    this.items.push({ x, y, z, vx, vy, vz, r, g, b, size, life, maxLife: life, gravity, drag });
  }
  update(dt) {
    const items = this.items;
    for (let i = items.length - 1; i >= 0; i--) {
      const p = items[i];
      p.life -= dt;
      if (p.life <= 0) { items[i] = items[items.length - 1]; items.pop(); continue; }
      p.vy -= p.gravity * dt;
      const d = Math.pow(p.drag, dt * 60);
      p.vx *= d; p.vy *= d; p.vz *= d;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
    }
    const n = items.length;
    for (let i = 0; i < n; i++) {
      const p = items[i];
      this.pos[i * 3] = p.x; this.pos[i * 3 + 1] = p.y; this.pos[i * 3 + 2] = p.z;
      this.col[i * 3] = p.r; this.col[i * 3 + 1] = p.g; this.col[i * 3 + 2] = p.b;
      const k = Math.max(0, p.life / p.maxLife);
      this.siz[i] = p.size * (0.45 + k * 0.85);
      this.alp[i] = Math.pow(k, 0.7);
    }
    this.geo.setDrawRange(0, n);
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
    this.geo.attributes.size.needsUpdate = true;
    this.geo.attributes.alpha.needsUpdate = true;
  }
}
const SPARKS = new ParticleField(520, THREE.AdditiveBlending, TEX.soft);
