    const vy = normal.y * rnd(1.0, 4.0) + rnd(0.2, 4.0);
    const vz = normal.z * rnd(1.0, 4.4) + rnd(-spread, spread);
    SPARKS.spawn(point.x + normal.x * 0.02, point.y + normal.y * 0.02, point.z + normal.z * 0.02,
      vx, vy, vz, baseCol[0] * rnd(0.75, 1), baseCol[1] * rnd(0.7, 1), baseCol[2] * rnd(0.65, 1),
