const DECALS = [];
for (let i = 0; i < 56; i++) {
  const mat = new THREE.MeshBasicMaterial({ map: TEX.decalConcrete, transparent: true, opacity: 0, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -4, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(1, 1), mat);
  mesh.visible = false;
  mesh.renderOrder = 3;
