}
let decalCursor = 0;
const Z_AXIS = new THREE.Vector3(0, 0, 1);
function addDecal(point, normal, type) {
  const d = DECALS[decalCursor++ % DECALS.length];
  d.mat.map = DECAL_TEX[type] || TEX.decalConcrete;
  d.mat.opacity = type === 'glass' ? 0.72 : 0.88;
