const TRACER_GEO = new THREE.CylinderGeometry(0.006, 0.014, 1, 5, 1, true);
const TRACER_Y = new THREE.Vector3(0, 1, 0);
function makeTracer(a, b) {
  const mat = new THREE.MeshBasicMaterial({ color: 0xffb765, transparent: true, opacity: 0.82, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(TRACER_GEO, mat);
  mesh.renderOrder = 5;
  scene.add(mesh);
  setTracer(mesh, a, b);
  return mesh;
}
function setTracer(mesh, a, b) {
  const d = _v.copy(b).sub(a);
  const len = d.length();
  if (len < 0.0001) return;
  mesh.position.copy(a).addScaledVector(d, 0.5);
  mesh.quaternion.setFromUnitVectors(TRACER_Y, d.normalize());
  mesh.scale.set(1, len, 1);
}

const CASINGS = [];
for (let i = 0; i < 26; i++) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.052, 6), MATS.brass);
  mesh.visible = false;
  mesh.castShadow = false;
  scene.add(mesh);
  CASINGS.push({ mesh, active: false, pos: new THREE.Vector3(), vel: new THREE.Vector3(), spin: new THREE.Vector3(), rot: new THREE.Euler(), life: 0, bounced: false });
}
let casingCursor = 0;
function ejectCasing(pos, right, up, forward) {
  const c = CASINGS[casingCursor++ % CASINGS.length];
  c.active = true;
  c.life = 4.5;
  c.bounced = false;
  c.pos.copy(pos);
  c.vel.set(
    right.x * rnd(2.2, 3.6) + up.x * rnd(1.1, 2.2) + forward.x * rnd(-0.4, 0.6),
    right.y * rnd(2.2, 3.6) + up.y * rnd(1.1, 2.2) + rnd(1.2, 2.4),
    right.z * rnd(2.2, 3.6) + up.z * rnd(1.1, 2.2) + forward.z * rnd(-0.4, 0.6)
  );
  c.spin.set(rnd(-18, 18), rnd(-18, 18), rnd(-18, 18));
  c.rot.set(rnd(0, TAU), rnd(0, TAU), rnd(0, TAU));
  c.mesh.visible = true;
  c.mesh.position.copy(pos);
}
function updateCasings(dt) {
  for (const c of CASINGS) {
    if (!c.active) continue;
    c.life -= dt;
    if (c.life <= 0) { c.active = false; c.mesh.visible = false; continue; }
    c.vel.y -= 17 * dt;
    c.pos.addScaledVector(c.vel, dt);
    const g = groundHeightAt(c.pos.x, c.pos.z, c.pos.y + 0.25);
    if (c.pos.y <= g + 0.018 && c.vel.y < 0) {
      c.pos.y = g + 0.018;
      c.vel.y *= -0.34;
      c.vel.x *= 0.56; c.vel.z *= 0.56;
      c.spin.multiplyScalar(0.55);
      if (!c.bounced) { c.bounced = true; SFX.casing(); }
      if (Math.abs(c.vel.y) < 0.32) c.vel.y = 0;
    }
    c.rot.x += c.spin.x * dt; c.rot.y += c.spin.y * dt; c.rot.z += c.spin.z * dt;
    c.mesh.position.copy(c.pos);
    c.mesh.rotation.copy(c.rot);
    c.mesh.visible = c.life > 0.45;
  }
}

/* muzzle flash / light */
const flashMat = new THREE.SpriteMaterial({ map: TEX.flash, color: 0xffcf94, transparent: true, blending: THREE.AdditiveBlending, depthTest: true, depthWrite: false });
