scene.add(flashLight.target);
let flashLightOn = false;
let flashLightTarget = 0;

/* =========================================================================
   PROCEDURAL AUDIO
   ========================================================================= */
const SFX = {
  ctx: null, master: null, muted: false, reverb: null, noise: null, ambientGain: null,
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AC();
      const ctx = this.ctx;
      this.master = ctx.createGain();
      this.master.gain.value = 0.52;
      this.master.connect(ctx.destination);
      const len = Math.floor(ctx.sampleRate * 0.95);
      const buf = ctx.createBuffer(1, len, ctx.sampleRate);
      const d = buf.getChannelData(0);
      for (let i = 0; i < len; i++) {
        const t = i / ctx.sampleRate;
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t / 0.95, 2.3);
      }
      this.reverb = ctx.createConvolver();
      this.reverb.buffer = buf;
      const wet = ctx.createGain(); wet.gain.value = 0.22;
      this.reverb.connect(wet).connect(this.master);
      const nb = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
      const nd = nb.getChannelData(0);
      for (let i = 0; i < nd.length; i++) nd[i] = Math.random() * 2 - 1;
      this.noise = nb;
      this.ambient();
    } catch (e) { console.warn('audio unavailable', e); }
  },
  ambient() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noise; src.loop = true;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 170;
    const g = ctx.createGain(); g.gain.value = 0.028;
    src.connect(lp).connect(g).connect(this.master);
    src.start();
    this.ambientGain = g;
    for (const f of [41, 57, 83]) {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f;
      const og = ctx.createGain(); og.gain.value = 0.006;
      o.connect(og).connect(this.master); o.start();
    }
  },
  send(node, wet = 0.3) {
    node.connect(this.master);
    if (this.reverb) {
      const g = this.ctx.createGain(); g.gain.value = wet;
      node.connect(g).connect(this.reverb);
    }
  },
  burst(dur, freq, q, gain, type = 'lowpass', wet = 0.25) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = ctx.createBufferSource(); src.buffer = this.noise;
    const f = ctx.createBiquadFilter(); f.type = type; f.frequency.value = freq; f.Q.value = q;
    const g = ctx.createGain(); g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f).connect(g); this.send(g, wet);
    src.start(t); src.stop(t + dur + 0.02);
  },
  shot() {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const src = ctx.createBufferSource(); src.buffer = this.noise;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass';
    lp.frequency.setValueAtTime(5200, t); lp.frequency.exponentialRampToValueAtTime(420, t + 0.28);
    const g = ctx.createGain(); g.gain.setValueAtTime(0.95, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.36);
    src.connect(lp).connect(g); this.send(g, 0.42);
    src.start(t); src.stop(t + 0.4);
    const crack = ctx.createBufferSource(); crack.buffer = this.noise;
    const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 1500;
    const cg = ctx.createGain(); cg.gain.setValueAtTime(0.42, t); cg.gain.exponentialRampToValueAtTime(0.0001, t + 0.045);
    crack.connect(hp).connect(cg); this.send(cg, 0.18);
    crack.start(t); crack.stop(t + 0.06);
    const o = ctx.createOscillator(); o.type = 'triangle'; o.frequency.setValueAtTime(108, t); o.frequency.exponentialRampToValueAtTime(42, t + 0.18);
    const og = ctx.createGain(); og.gain.setValueAtTime(0.52, t); og.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
    o.connect(og); this.send(og, 0.16); o.start(t); o.stop(t + 0.24);
  },
  ding(strong = false) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const base = strong ? 980 : 1450;
    for (const [f, gain, dur] of [[base, 0.3, 1.1], [base * 1.62, 0.18, 0.8], [base * 2.41, 0.1, 0.55]]) {
      const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = f;
      const g = ctx.createGain(); g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g); this.send(g, 0.5); o.start(t); o.stop(t + dur + 0.02);
    }
  },
  impact(kind) {
    if (!this.ctx) return;
    if (kind === 'metal') this.burst(0.09, 2600, 1.4, 0.2, 'bandpass', 0.3);
    else if (kind === 'glass') this.burst(0.16, 4800, 0.9, 0.18, 'highpass', 0.25);
    else if (kind === 'wood') this.burst(0.1, 760, 1.1, 0.16, 'bandpass', 0.16);
    else this.burst(0.11, 520, 0.8, 0.14, 'lowpass', 0.16);
  },
  click(freq = 900, dur = 0.035, gain = 0.14) {
    if (!this.ctx) return;
    const ctx = this.ctx, t = ctx.currentTime;
    const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = freq;
    const g = ctx.createGain(); g.gain.setValueAtTime(gain, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); this.send(g, 0.08); o.start(t); o.stop(t + dur + 0.01);
  },
  magOut() { this.click(360, 0.05, 0.16); this.burst(0.08, 900, 1.0, 0.12, 'bandpass', 0.1); },
  magIn() { this.click(520, 0.045, 0.18); },
  bolt() { this.click(1150, 0.05, 0.16); this.burst(0.07, 2200, 1.4, 0.14, 'bandpass', 0.12); },
  casing() { this.click(2800, 0.035, 0.06); },
  step(surface) {
    if (!this.ctx) return;
    this.burst(0.085, surface ? 900 : 460, 0.8, surface ? 0.075 : 0.055, 'lowpass', 0.06);
  },
  empty() { this.click(620, 0.04, 0.12); },
  toggleMute() {
    this.muted = !this.muted;
    if (this.master) this.master.gain.value = this.muted ? 0 : 0.52;
  },
};

