function addStairs(x, zTop, width, steps, rise, run, floorY, dir = 1) {
  for (let i = 0; i < steps; i++) {
    const y = floorY + i * rise + rise / 2;
    const z = zTop + dir * i * run;
    B.box(width, rise, run + 0.02, x, y, z, 'concrete', { uv: 0.7, collide: true });
  }
  const topY = floorY + steps * rise;
  const topZ = zTop + dir * steps * run;
  B.box(width + 0.2, 0.18, 1.2, x, topY - 0.09, topZ + dir * 0.5, 'concrete', { uv: 0.6, collide: true });
  for (const s of [-1, 1]) {
    for (let i = 0; i < steps; i += 3) {
      const z = zTop + dir * i * run;
      const y = floorY + i * rise;
      B.cyl(0.022, 0.022, 1.0, 6, x + s * (width / 2 + 0.03), y + 0.5, z, 'metalDark', {});
    }
    const railLen = Math.hypot(steps * run, steps * rise);
    B.box(0.05, 0.05, railLen, x + s * (width / 2 + 0.03), floorY + steps * rise / 2 + 0.95, zTop + dir * steps * run / 2, 'metalDark', { rx: -dir * Math.atan2(steps * rise, steps * run) });
  }
  return { topY, topZ };
}
function addACUnit(x, y, z, ry = 0, s = 1) {
  const base = M4(x, y, z, 0, ry);
  localAdd(base, new THREE.BoxGeometry(1.1 * s, 0.75 * s, 0.7 * s), 'metalDark', 0, 0, 0);
  localAdd(base, new THREE.CylinderGeometry(0.27 * s, 0.27 * s, 0.03, 18), 'blackPaint', 0, 0, 0.36 * s, Math.PI / 2, 0, 0);
  for (let i = 0; i < 4; i++) localAdd(base, new THREE.BoxGeometry(0.95 * s, 0.02, 0.02), 'metalDark', 0, -0.25 * s + i * 0.16 * s, 0.36 * s);
  localAdd(base, new THREE.BoxGeometry(1.15 * s, 0.05, 0.75 * s), 'metalDark', 0, 0.4 * s, 0);
}

