function updateWeapon(dt, time) {
  const ads = GAME.ads;
  GAME.kickZ = damp(GAME.kickZ, 0, 17, dt);
  GAME.kickY = damp(GAME.kickY, 0, 17, dt);
  GAME.kickRot = damp(GAME.kickRot, 0, 16, dt);
  GAME.swayX = damp(GAME.swayX, 0, 9, dt);
  GAME.swayY = damp(GAME.swayY, 0, 9, dt);
  GAME.boltKick = damp(GAME.boltKick, 0, 22, dt);

  const reloadP = GAME.reloading ? clamp(GAME.reloadT / GAME.reloadDur, 0, 1) : 0;
  const reloadAnim = GAME.reloading ? Math.sin(Math.PI * reloadP) : 0;
  let insp = 0;
  if (GAME.inspectT > 0) insp = Math.sin(Math.PI * (1 - GAME.inspectT / GAME.inspectDur));

  const hipX = 0.168, hipY = -0.148, hipZ = -0.305;
  const adsX = 0.0, adsY = -0.094, adsZ = -0.252;
  let tx = lerp(hipX, adsX, ads);
  let ty = lerp(hipY, adsY, ads);
  let tz = lerp(hipZ, adsZ, ads);

  const bobAmp = clamp(player.speed / 5.2, 0, 1.4) * (1 - ads * 0.82) * (player.onGround ? 1 : 0.25);
  const bx = Math.sin(player.bobPhase) * 0.0075 * bobAmp;
  const by = Math.abs(Math.cos(player.bobPhase)) * 0.0065 * bobAmp;
  tx += bx + GAME.swayX * 0.35;
  ty += by - GAME.swayY * 0.35;
  tx += Math.sin(time * 1.35) * 0.0018 * (1 - ads);
  ty += Math.cos(time * 1.05) * 0.0014 * (1 - ads);

  if (player.sprint) {
    tx += 0.035; ty -= 0.105; tz += 0.045;
  }
  if (player.crouched) ty -= 0.012;
  if (GAME.reloading) {
    tx += 0.045 * reloadAnim;
    ty -= 0.105 * reloadAnim;
    tz += 0.035 * reloadAnim;
  }
  if (insp > 0) {
    tx -= 0.14 * insp;
    ty += 0.05 * insp;
    tz += 0.03 * insp;
  }
  tx += GAME.kickZ * 0.1;
  ty += GAME.kickY;
  tz += GAME.kickZ;

  weaponRoot.position.x = damp(weaponRoot.position.x, tx, 15, dt);
  weaponRoot.position.y = damp(weaponRoot.position.y, ty, 15, dt);
  weaponRoot.position.z = damp(weaponRoot.position.z, tz, 15, dt);

  let rx = lerp(0.018, 0.0, ads) + GAME.kickRot * 0.55 + Math.cos(time * 1.1) * 0.0025 * (1 - ads);
  let ry = lerp(-0.05, 0.0, ads) + GAME.swayX * 0.7;
  let rz = lerp(0.008, 0.0, ads) - GAME.swayX * 0.4 + Math.sin(time * 0.9) * 0.002 * (1 - ads);
  if (player.sprint) { rx -= 0.28; rz += 0.13; ry += 0.08; }
  if (GAME.reloading) { rx += 0.13 * reloadAnim; rz += 0.62 * reloadAnim; ry -= 0.16 * reloadAnim; }
  if (insp > 0) { ry += 1.02 * insp; rz -= 0.42 * insp; rx += 0.18 * insp; }
  rx += GAME.kickRot;
  weaponRoot.rotation.x = damp(weaponRoot.rotation.x, rx, 16, dt);
  weaponRoot.rotation.y = damp(weaponRoot.rotation.y, ry, 16, dt);
  weaponRoot.rotation.z = damp(weaponRoot.rotation.z, rz, 16, dt);

  const magDrop = GAME.reloading
    ? smooth(clamp((reloadP - 0.16) / 0.2, 0, 1)) * (1 - smooth(clamp((reloadP - 0.6) / 0.2, 0, 1)))
    : 0;
  magazine.position.y = -0.086 - magDrop * 0.29;
  magazine.position.z = -0.083 - magDrop * 0.035;
  magazine.rotation.z = magDrop * 0.46;

  const boltPull = GAME.reloading
    ? smooth(clamp((reloadP - 0.67) / 0.12, 0, 1)) * (1 - smooth(clamp((reloadP - 0.8) / 0.1, 0, 1)))
    : 0;
  boltGroup.position.z = -0.14 + GAME.boltKick * 0.033 + boltPull * 0.038;

  if (GAME.weaponFlashT > 0) {
    GAME.weaponFlashT -= dt;
    weaponFlash.visible = true;
    const k = clamp(GAME.weaponFlashT / 0.045, 0, 1);
    weaponFlash.scale.setScalar(lerp(0.16, 0.27, k));
    weaponFlash.material.rotation = rnd(0, TAU);
    weaponFlash.material.opacity = k;
    weaponFlashLight.intensity = 4.5 * k;
  } else {
    weaponFlash.visible = false;
    weaponFlashLight.intensity = 0;
  }
}

