function updateHud() {
  hud.mag.textContent = GAME.ammo;
  hud.reserve.textContent = GAME.reserve;
  hud.ammo.classList.toggle('low', GAME.ammo <= 6);
  hud.score.textContent = GAME.score;
  hud.reloadbar.classList.toggle('on', GAME.reloading);
  hud.reloadFill.style.width = GAME.reloading ? (clamp(GAME.reloadT / GAME.reloadDur, 0, 1) * 100).toFixed(1) + '%' : '0%';
  let stance = 'STANDING';
  if (GAME.reloading) stance = 'RELOADING';
  else if (player.sprint) stance = 'SPRINTING';
  else if (player.crouched) stance = 'CROUCHED';
  else if (GAME.ads > 0.55) stance = 'AIMING';
  hud.stance.textContent = stance;
  hud.crosshair.classList.toggle('ads', GAME.ads > 0.58);
}
let hitTimer = 0;
function showHitmarker(kill) {
  hud.hitmarker.classList.remove('show', 'kill');
  void hud.hitmarker.offsetWidth;
  hud.hitmarker.classList.add('show');
  if (kill) hud.hitmarker.classList.add('kill');
  clearTimeout(hitTimer);
  hitTimer = setTimeout(() => hud.hitmarker.classList.remove('show', 'kill'), kill ? 220 : 110);
}
let hintTimer = 0;
function flashHint(text, dur = 2400) {
  hud.hint.textContent = text;
  hud.hint.classList.remove('gone');
  clearTimeout(hintTimer);
  hintTimer = setTimeout(() => hud.hint.classList.add('gone'), dur);
}

function startReload() {
  if (!GAME.started || GAME.reloading || GAME.ammo >= 30 || GAME.reserve <= 0) return;
  GAME.reloading = true;
  GAME.reloadT = 0;
  GAME.reloadSfx = 0;
  GAME.inspectT = 0;
  GAME.adsHeld = false;
  SFX.click(320, 0.045, 0.1);
  updateHud();
}
function updateReload(dt) {
  if (!GAME.reloading) return;
  GAME.reloadT += dt;
  const p = GAME.reloadT / GAME.reloadDur;
  if (p >= 0.16 && GAME.reloadSfx < 1) { GAME.reloadSfx = 1; SFX.magOut(); }
  if (p >= 0.53 && GAME.reloadSfx < 2) { GAME.reloadSfx = 2; SFX.magIn(); }
  if (p >= 0.8 && GAME.reloadSfx < 3) { GAME.reloadSfx = 3; SFX.bolt(); }
  if (p >= 1) {
    const need = Math.min(30 - GAME.ammo, GAME.reserve);
    GAME.ammo += need;
    GAME.reserve -= need;
    GAME.reloading = false;
    GAME.reloadT = 0;
    GAME.reloadSfx = 0;
    updateHud();
  } else {
    hud.reloadFill.style.width = (clamp(p, 0, 1) * 100).toFixed(1) + '%';
  }
}

function fireShot() {
  if (!GAME.started || GAME.reloading) return;
  if (GAME.inspectT > 0) GAME.inspectT = 0;
  if (GAME.ammo <= 0) {
    GAME.fireTimer = 0.36;
    SFX.empty();
    if (GAME.reserve > 0) startReload();
    return;
  }
  GAME.ammo--;
  GAME.shots++;
  GAME.fireTimer = 0.1;
  GAME.heat = Math.min(1, GAME.heat + 0.11);
  hud.hint.classList.add('gone');

  const ads = GAME.ads;
  const spread = lerp(0.0092, 0.0014, ads) + clamp(player.speed / 7, 0, 1) * 0.0065 + (player.onGround ? 0 : 0.018) + GAME.heat * 0.0052;
  const dir = camera.getWorldDirection(_tmpV).clone();
  const r = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
  const u = new THREE.Vector3(0, 1, 0).applyQuaternion(camera.quaternion);
  dir.addScaledVector(r, rnd(-spread, spread)).addScaledVector(u, rnd(-spread, spread)).normalize();

  const origin = camera.position.clone();
  const start = origin.clone();
  _muzzle.copy(camera.position)
    .addScaledVector(_fwd, lerp(0.66, 0.82, ads))
    .addScaledVector(_right, lerp(0.17, 0.015, ads))
    .addScaledVector(_up, lerp(-0.13, -0.062, ads));
  const tracer = makeTracer(_muzzle, start);
  BULLETS.push({
    pos: origin.clone(), prev: origin.clone(), vel: dir.multiplyScalar(760),
    life: 2.6, dead: false, tracerLife: 0, tracer, start: _muzzle.clone(),
  });

  worldFlash.position.copy(_muzzle);
  worldFlash.material.rotation = rnd(0, TAU);
  worldFlash.scale.setScalar(rnd(0.44, 0.7));
  worldFlash.material.opacity = 1;
  worldFlash.visible = true;
  worldFlashT = 0.05;
  worldFlashLight.position.copy(_muzzle);
  worldFlashLight.intensity = 24;

  weaponFlash.visible = true;
  GAME.weaponFlashT = 0.045;

  const eject = camera.position.clone()
    .addScaledVector(_fwd, 0.5)
    .addScaledVector(_right, 0.2)
    .addScaledVector(_up, -0.055);
  ejectCasing(eject, _right, _up, _fwd);

  GAME.kickZ += 0.034 + rnd(0.0, 0.012);
  GAME.kickY += 0.009;
  GAME.kickRot += 0.05 + rnd(0.0, 0.025);
  GAME.boltKick = 1;
  GAME.recoilPitch += (0.0115 + rnd(0.0, 0.0045)) * (1 - ads * 0.34);
  GAME.recoilYaw += rnd(-0.0048, 0.0048) * (1 - ads * 0.42);
  player.shake = Math.min(1.1, player.shake + 0.12);
  GAME.swayX += rnd(-0.004, 0.004);

  SFX.shot();
  if (GAME.ammo === 0 && GAME.reserve > 0) flashHint('MAG EMPTY · RELOADING', 1400);
  updateHud();
}

function updateFiring(dt) {
  GAME.fireTimer = Math.max(0, GAME.fireTimer - dt);
  GAME.heat = damp(GAME.heat, 0, 2.4, dt);
  if (GAME.inspectT > 0) GAME.inspectT = Math.max(0, GAME.inspectT - dt);
  if (GAME.firing && GAME.started && !GAME.paused && !GAME.reloading && !player.sprint && GAME.inspectT <= 0 && GAME.fireTimer <= 0) {
    fireShot();
  }
}

function impactType(key) {
  if (!key) return 'concrete';
  if (key.includes('brick')) return 'brick';
  if (key.includes('wood') || key.includes('plank') || key.includes('doorWood')) return 'wood';
  if (key.includes('glass') || key.includes('window')) return 'glass';
  if (key.includes('metal') || key.includes('rust') || key.includes('chrome') || key.includes('steel') ||
      key.includes('corrugated') || key.includes('signal') || key.includes('headlight') || key.includes('taillight') ||
      key.includes('paint') || key.includes('target')) return 'metal';
  return 'concrete';
}

function handleImpact(hit, bullet) {
  bullet.pos.copy(hit.point);
  const normal = hit.face ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld) : _up.clone();
  const target = hit.object.userData.target;
  const key = hit.object.userData.mat || (target ? 'targetSteel' : 'concrete');
  const type = target ? 'metal' : impactType(key);
  spawnImpact(hit.point, normal, type);
  if (!target) addDecal(hit.point, normal, type);
  SFX.impact(type);
  if (target && !target.down) {
    target.vel += 7.2;
    target.hits++;
    GAME.score++;
    const kill = target.hits >= 5;
    if (kill) {
      target.down = true;
      target.downT = 4.2;
      target.vel = 0;
    }
    showHitmarker(kill);
    SFX.ding(kill);
    updateHud();
  }
  setTracer(bullet.tracer, bullet.start, hit.point);
}

function updateBullets(dt) {
  for (let i = BULLETS.length - 1; i >= 0; i--) {
    const b = BULLETS[i];
    if (b.dead) {
      b.tracerLife -= dt;
      b.tracer.material.opacity = clamp(b.tracerLife / 0.055, 0, 1) * 0.82;
      if (b.tracerLife <= 0) {
        scene.remove(b.tracer);
        b.tracer.material.dispose();
        BULLETS.splice(i, 1);
      }
      continue;
    }
    b.vel.y -= 9.81 * dt;
    b.prev.copy(b.pos);
    b.pos.addScaledVector(b.vel, dt);
    _seg.copy(b.pos).sub(b.prev);
    const dist = _seg.length();
    let hit = null;
    if (dist > 0.0001) {
      _ray.set(b.prev, _seg.multiplyScalar(1 / dist));
      _ray.far = dist;
      const hits = _ray.intersectObjects(RAYCAST_OBJECTS, false);
      if (hits.length) hit = hits[0];
    }
    if (hit) {
      handleImpact(hit, b);
      b.dead = true;
      b.tracerLife = 0.055;
    } else {
      setTracer(b.tracer, b.start, b.pos);
    }
    b.life -= dt;
    if (b.life <= 0) { b.dead = true; b.tracerLife = 0; }
  }
}

function updateTargets(dt) {
  for (const t of TARGETS) {
    if (t.down) {
      t.downT -= dt;
      t.pivot.rotation.x = damp(t.pivot.rotation.x, 1.46, 5, dt);
      if (t.downT <= 0) {
        t.down = false;
        t.hits = 0;
        t.angle = 0;
        t.vel = 0;
        t.pivot.rotation.x = 0;
      }
    } else {
      t.vel += (-62 * t.angle - 8.5 * t.vel) * dt;
      t.angle += t.vel * dt;
      if (Math.abs(t.angle) < 0.0004 && Math.abs(t.vel) < 0.002) { t.angle = 0; t.vel = 0; }
      t.pivot.rotation.x = t.angle;
    }
  }
}

/* =========================================================================
   INPUT / POINTER LOCK
   ========================================================================= */
function requestLock() {
  if (document.pointerLockElement === canvas) return;
  try {
    const p = canvas.requestPointerLock();
    if (p && p.catch) p.catch(() => { GAME.lookFallback = true; flashHint('POINTER LOCK UNAVAILABLE · DRAG TO LOOK', 5000); });
  } catch (e) {
    GAME.lookFallback = true;
    flashHint('POINTER LOCK UNAVAILABLE · DRAG TO LOOK', 5000);
  }
}
function startGame(lock = true) {
  SFX.init();
  GAME.started = true;
  GAME.paused = false;
  GAME.ignoreUnlockUntil = performance.now() + 1200;
  $('#start').classList.add('hidden');
  $('#pause').classList.add('hidden');
  document.body.classList.add('playing');
  updateHud();
  hud.hint.textContent = 'ESC RELEASES CURSOR · R RELOAD · F INSPECT';
  hud.hint.classList.remove('gone');
  clearTimeout(hintTimer);
  hintTimer = setTimeout(() => hud.hint.classList.add('gone'), 9000);
  if (lock) setTimeout(requestLock, 30);
}
function pauseGame() {
  if (!GAME.started || GAME.paused) return;
  GAME.paused = true;
  GAME.firing = false;
  GAME.adsHeld = false;
  keys.w = keys.a = keys.s = keys.d = keys.shift = keys.space = false;
  $('#pause').classList.remove('hidden');
}
function resumeGame() {
  if (!GAME.started) return;
  GAME.paused = false;
  GAME.ignoreUnlockUntil = performance.now() + 1200;
  $('#pause').classList.add('hidden');
  requestLock();
}

$('#startBtn').addEventListener('click', () => startGame(true));
$('#resumeBtn').addEventListener('click', () => resumeGame());

document.addEventListener('pointerlockchange', () => {
  if (document.pointerLockElement === canvas) {
    GAME.locked = true;
    GAME.lookFallback = false;
    GAME.paused = false;
    $('#pause').classList.add('hidden');
  } else {
    GAME.locked = false;
    if (GAME.started && !GAME.paused && performance.now() > GAME.ignoreUnlockUntil) pauseGame();
  }
});
document.addEventListener('pointerlockerror', () => {
  GAME.lookFallback = true;
  flashHint('POINTER LOCK UNAVAILABLE · DRAG TO LOOK', 5000);
});

document.addEventListener('keydown', (e) => {
  if (e.code === 'F3') { e.preventDefault(); toggleDebug(); return; }
  if (e.code === 'KeyM' && !e.repeat) { SFX.init(); SFX.toggleMute(); flashHint(SFX.muted ? 'AUDIO MUTED' : 'AUDIO ON', 1200); return; }
  if (!GAME.started) return;
  switch (e.code) {
    case 'KeyW': keys.w = true; break;
    case 'KeyA': keys.a = true; break;
    case 'KeyS': keys.s = true; break;
    case 'KeyD': keys.d = true; break;
    case 'ShiftLeft': case 'ShiftRight': keys.shift = true; break;
    case 'Space': keys.space = true; e.preventDefault(); break;
    case 'KeyC':
      if (!e.repeat) { player.crouched = !player.crouched; updateHud(); }
      break;
    case 'KeyR':
      if (!e.repeat) startReload();
      break;
    case 'KeyF':
      if (!e.repeat && !GAME.reloading) { GAME.inspectT = GAME.inspectDur; GAME.inspectDur = 2.2; SFX.click(1450, 0.03, 0.08); }
      break;
    case 'KeyE':
      if (!e.repeat) {
        flashLightOn = !flashLightOn;
        flashLightTarget = flashLightOn ? 1 : 0;
        flashHint(flashLightOn ? 'WEAPON LIGHT ON' : 'WEAPON LIGHT OFF', 1400);
        SFX.click(flashLightOn ? 1700 : 1200, 0.03, 0.08);
      }
      break;
  }
});
document.addEventListener('keyup', (e) => {
  switch (e.code) {
    case 'KeyW': keys.w = false; break;
    case 'KeyA': keys.a = false; break;
    case 'KeyS': keys.s = false; break;
    case 'KeyD': keys.d = false; break;
    case 'ShiftLeft': case 'ShiftRight': keys.shift = false; break;
    case 'Space': keys.space = false; break;
  }
});
window.addEventListener('blur', () => {
  keys.w = keys.a = keys.s = keys.d = keys.shift = keys.space = false;
  GAME.firing = false;
  GAME.adsHeld = false;
});

canvas.addEventListener('contextmenu', (e) => e.preventDefault());
canvas.addEventListener('mousedown', (e) => {
  if (!GAME.started) return;
  if (GAME.paused) { resumeGame(); return; }
  if (!GAME.locked && !GAME.lookFallback) { requestLock(); return; }
  if (e.button === 0) GAME.firing = true;
  if (e.button === 2) GAME.adsHeld = true;
});
window.addEventListener('mouseup', (e) => {
  if (e.button === 0) GAME.firing = false;
  if (e.button === 2) GAME.adsHeld = false;
});
document.addEventListener('mousemove', (e) => {
  if (!GAME.started || GAME.paused) return;
  const locked = document.pointerLockElement === canvas;
  if (!locked && !(GAME.lookFallback && (e.buttons & 3))) return;
  const sens = 0.00205 * (1 - GAME.ads * 0.34);
  const dx = e.movementX || 0, dy = e.movementY || 0;
  player.yaw -= dx * sens;
  player.pitch = clamp(player.pitch - dy * sens, -1.46, 1.46);
  GAME.swayX = clamp(dx * 0.00028, -0.012, 0.012);
  GAME.swayY = clamp(dy * 0.00024, -0.012, 0.012);
});

/* =========================================================================
   HUD / COMPASS / DEBUG
   ========================================================================= */
const hud = {
  mag: $('#mag'), reserve: $('#reserve'), ammo: $('#ammo'), score: $('#score'),
  stance: $('#stance'), crosshair: $('#crosshair'), hitmarker: $('#hitmarker'),
  hint: $('#hint'), reloadbar: $('#reloadbar'), reloadFill: $('#reloadbar i'),
};
const compass = $('#compass');
const cctx = compass.getContext('2d');
function drawCompass() {
  const w = 300, h = 36;
  cctx.clearRect(0, 0, w, h);
  cctx.fillStyle = 'rgba(8,10,11,.28)';
  cctx.fillRect(0, 10, w, 18);
  cctx.strokeStyle = 'rgba(255,255,255,.12)';
  cctx.beginPath(); cctx.moveTo(0, 10.5); cctx.lineTo(w, 10.5); cctx.moveTo(0, 27.5); cctx.lineTo(w, 27.5); cctx.stroke();
  const heading = ((-player.yaw * 180 / Math.PI) % 360 + 360) % 360;
  const scale = 2.0;
  for (let d = -58; d <= 58; d += 5) {
    const hd = ((heading + d) % 360 + 360) % 360;
    const x = w / 2 + d * scale;
    const major = Math.abs(hd % 15) < 0.5;
    cctx.strokeStyle = major ? 'rgba(240,236,224,.65)' : 'rgba(255,255,255,.22)';
    cctx.lineWidth = major ? 1.3 : 1;
    cctx.beginPath();
    cctx.moveTo(x, 14);
    cctx.lineTo(x, major ? 22 : 19);
    cctx.stroke();
  }
  const cards = [['N', 0], ['E', 90], ['S', 180], ['W', 270]];
  cctx.font = '700 10px ui-monospace, monospace';
  cctx.textAlign = 'center';
  for (const [label, ang] of cards) {
    let delta = ((ang - heading + 540) % 360) - 180;
    if (Math.abs(delta) > 55) continue;
    const x = w / 2 + delta * scale;
    cctx.fillStyle = label === 'N' ? '#ff8b3d' : 'rgba(230,226,214,.78)';
    cctx.fillText(label, x, 32);
  }
  cctx.fillStyle = '#ff7a2a';
  cctx.beginPath(); cctx.moveTo(w / 2, 7); cctx.lineTo(w / 2 - 4, 1); cctx.lineTo(w / 2 + 4, 1); cctx.closePath(); cctx.fill();
  cctx.fillStyle = 'rgba(255,255,255,.7)';
  cctx.fillRect(w / 2 - 0.5, 11, 1, 16);
}

let debugOn = false, debugTimer = 0, fpsFrames = 0, fpsAccum = 0, fpsNow = 60;
function toggleDebug() {
  debugOn = !debugOn;
  $('#debug').classList.toggle('on', debugOn);
}
function updateDebug(dt) {
  fpsFrames++;
  fpsAccum += dt;
  if (fpsAccum >= 0.5) {
    fpsNow = fpsFrames / fpsAccum;
    fpsFrames = 0; fpsAccum = 0;
    if (debugOn) {
      const info = renderer.info.render;
      $('#debug').textContent =
        `FPS ${fpsNow.toFixed(0)}  ${(1000 / Math.max(1, fpsNow)).toFixed(1)}ms\n` +
        `CALLS ${info.calls}  TRIS ${(info.triangles / 1000).toFixed(0)}k\n` +
        `POS ${player.pos.x.toFixed(1)} ${player.pos.y.toFixed(2)} ${player.pos.z.toFixed(1)}\n` +
        `MAG ${GAME.ammo}/${GAME.reserve}  TGT ${GAME.score}  ERR ${window.__errors.length}`;
    }
  }
}

/* =========================================================================
   MAIN LOOP
   ========================================================================= */
const clock = new THREE.Clock();
let elapsed = 0;
const dustGeo = new THREE.BufferGeometry();
{
  const n = 520, p = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    p[i * 3] = rnd(-55, 55);
    p[i * 3 + 1] = rnd(0.4, 16);
    p[i * 3 + 2] = rnd(-55, 55);
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(p, 3));
}
const dustMat = new THREE.PointsMaterial({ color: 0xe7d3ae, size: 0.035, map: TEX.soft, transparent: true, opacity: 0.26, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
const dust = new THREE.Points(dustGeo, dustMat);
dust.frustumCulled = false;
scene.add(dust);

function updateEffects(dt) {
  SPARKS.update(dt);
  SMOKE.update(dt);
  updateDecals(dt);
  updateCasings(dt);
  dust.rotation.y += dt * 0.004;
  if (worldFlashT > 0) {
    worldFlashT -= dt;
    const k = clamp(worldFlashT / 0.05, 0, 1);
    worldFlash.material.opacity = k;
    worldFlash.scale.setScalar(lerp(0.28, 0.7, k));
    worldFlashLight.intensity = 24 * k;
    if (worldFlashT <= 0) { worldFlash.visible = false; worldFlashLight.intensity = 0; }
  } else {
    worldFlashLight.intensity = damp(worldFlashLight.intensity, 0, 20, dt);
  }
}

function frame() {
  requestAnimationFrame(frame);
  const dt = Math.min(0.05, clock.getDelta());
  elapsed += dt;
  skyUniforms.uTime.value = elapsed;

  GAME.ads = damp(GAME.ads, (GAME.adsHeld && !GAME.reloading && !player.sprint) ? 1 : 0, 11, dt);
  if (GAME.started && !GAME.paused) {
    updatePlayer(dt, elapsed);
    updateReload(dt);
    updateFiring(dt);
    updateWeapon(dt, elapsed);
    updateHud();
  } else {
    updateWeapon(dt, elapsed);
  }
  updateBullets(dt);
  updateTargets(dt);
  updateEffects(dt);
  drawCompass();
  updateDebug(dt);

  renderer.clear();
  renderer.render(scene, camera);
  renderer.clearDepth();
  renderer.render(weaponScene, weaponCamera);
}

camera.position.set(player.pos.x, player.pos.y + player.eye, player.pos.z);
camera.rotation.set(player.pitch, player.yaw, 0);
updateHud();
requestAnimationFrame(frame);

requestAnimationFrame(() => {
  $('#loadbar').style.width = '100%';
  $('#loadpct').textContent = '100%';
  setTimeout(() => $('#loading').classList.add('hidden'), 320);
});

/* =========================================================================
   AUTOMATION / DEBUG API
   ========================================================================= */
window.__GZ = {
  start() {
    startGame(false);
    GAME.paused = false;
    $('#pause').classList.add('hidden');
    return this.state();
  },
  setView(yaw, pitch) { player.yaw = yaw; player.pitch = clamp(pitch, -1.4, 1.4); },
  teleport(x, y, z) { player.pos.set(x, y, z); player.vel.set(0, 0, 0); },
  ads(on) { GAME.adsHeld = !!on; },
  fire(on = true) { GAME.firing = !!on; if (on) GAME.fireTimer = 0; },
  reload: startReload,
  inspect() { GAME.inspectT = GAME.inspectDur; },
  light(on) { flashLightOn = !!on; flashLightTarget = on ? 1 : 0; },
  crouch(on) { player.crouched = !!on; },
  hideOverlays() {
    $('#start').classList.add('hidden');
    $('#pause').classList.add('hidden');
    $('#loading').classList.add('hidden');
    document.body.classList.add('playing');
  },
  state() {
    return {
      started: GAME.started, paused: GAME.paused, pos: player.pos.toArray(),
      yaw: player.yaw, pitch: player.pitch, ammo: GAME.ammo, reserve: GAME.reserve,
      score: GAME.score, reloading: GAME.reloading, targets: TARGETS.length,
      errors: window.__errors.slice(),
    };
  },
  scene, camera, player, game: GAME, targets: TARGETS,
};
</script>
</body>
</html>

