+/* =========================================================================
+   PLAYER + GAME STATE
+   ========================================================================= */
+const canvas = renderer.domElement;
+const EYE_STAND = 1.67, EYE_CROUCH = 1.02, H_STAND = 1.74, H_CROUCH = 1.12;
+const PLAYER_RADIUS = 0.34, STEP_HEIGHT = 0.34, GRAVITY = 18.0;
+const keys = { w: false, a: false, s: false, d: false, shift: false, space: false };
+const player = {
+  pos: new THREE.Vector3(-10.55, 0.14, 12.2),
+  vel: new THREE.Vector3(),
+  yaw: -0.22, pitch: -0.025, roll: 0,
+  eye: EYE_STAND, height: H_STAND,
+  crouched: false, onGround: true, wasAir: false,
+  bobPhase: 0, stepDist: 0, landKick: 0, shake: 0,
+  speed: 0, sprint: false, strafe: 0,
+};
+const GAME = {
+  started: false, paused: false, locked: false, lookFallback: false,
+  ammo: 30, reserve: 120, reloading: false, reloadT: 0, reloadDur: 2.4, reloadSfx: 0,
+  firing: false, adsHeld: false, ads: 0, fireTimer: 0, heat: 0,
+  recoilPitch: 0, recoilYaw: 0, kickZ: 0, kickY: 0, kickRot: 0, boltKick: 0,
+  swayX: 0, swayY: 0, inspectT: 0, inspectDur: 2.2,
+  weaponFlashT: 0, score: 0, shots: 0, ignoreUnlockUntil: 0,
+};
+const BULLETS = [];
+const _ray = new THREE.Raycaster();
+const _fwd = new THREE.Vector3();
+const _right = new THREE.Vector3();
+const _up = new THREE.Vector3();
+const _seg = new THREE.Vector3();
+const _muzzle = new THREE.Vector3();
+const _tmpV = new THREE.Vector3();
+
+function circleOverlap(c, x, z, r) {
+  const nx = clamp(x, c.cx - c.hx, c.cx + c.hx);
+  const nz = clamp(z, c.cz - c.hz, c.cz + c.hz);
+  const dx = x - nx, dz = z - nz;
+  return dx * dx + dz * dz < r * r;
+}
+function blockedAt(x, z, feet, height) {
+  for (const c of COLLIDERS) {
+    if (c.maxY <= feet + STEP_HEIGHT + 0.015) continue;
+    if (c.minY >= feet + height - 0.04) continue;
+    if (circleOverlap(c, x, z, PLAYER_RADIUS)) return true;
+  }
+  return false;
+}
+function groundHeightAt(x, z, feetY) {
+  let best = 0;
+  for (const c of COLLIDERS) {
+    if (c.maxY > feetY + STEP_HEIGHT + 0.03) continue;
+    if (circleOverlap(c, x, z, PLAYER_RADIUS * 0.92) && c.maxY > best) best = c.maxY;
+  }
+  return best;
+}
+
+function updatePlayer(dt, time) {
+  const ix = (keys.d ? 1 : 0) - (keys.a ? 1 : 0);
+  const iz = (keys.w ? 1 : 0) - (keys.s ? 1 : 0);
+  const inputLen = Math.hypot(ix, iz);
+  const moving = inputLen > 0.01;
+  const sin = Math.sin(player.yaw), cos = Math.cos(player.yaw);
+  let dx = 0, dz = 0;
+  if (moving) {
+    const nx = ix / inputLen, nz = iz / inputLen;
+    dx = nx * cos - nz * sin;
+    dz = -nx * sin - nz * cos;
+  }
+  const adsFactor = GAME.ads;
+  player.sprint = keys.shift && iz > 0 && !player.crouched && adsFactor < 0.25 && !GAME.reloading && player.onGround;
+  let speed = player.sprint ? 7.0 : 4.35;
+  if (player.crouched) speed = 2.35;
+  else if (GAME.reloading) speed = 3.2;
+  if (adsFactor > 0.3) speed = lerp(speed, 2.75, adsFactor);
+  const desiredX = dx * speed, desiredZ = dz * speed;
+  const accel = player.onGround ? 15 : 3.2;
+  player.vel.x = damp(player.vel.x, desiredX, accel, dt);
+  player.vel.z = damp(player.vel.z, desiredZ, accel, dt);
+  if (!moving && player.onGround) {
+    player.vel.x = damp(player.vel.x, 0, 18, dt);
+    player.vel.z = damp(player.vel.z, 0, 18, dt);
+  }
+
+  if (keys.space && player.onGround && !player.crouched) {
+    player.vel.y = 5.45;
+    player.onGround = false;
+    SFX.step(false);
+  }
+
+  const height = player.crouched ? H_CROUCH : H_STAND;
+  const nx = player.pos.x + player.vel.x * dt;
+  if (!blockedAt(nx, player.pos.z, player.pos.y, height)) player.pos.x = nx;
+  else player.vel.x = 0;
+  const nz = player.pos.z + player.vel.z * dt;
+  if (!blockedAt(player.pos.x, nz, player.pos.y, height)) player.pos.z = nz;
+  else player.vel.z = 0;
+
+  player.vel.y -= GRAVITY * dt;
+  const prevFeet = player.pos.y;
+  player.pos.y += player.vel.y * dt;
+  const g = groundHeightAt(player.pos.x, player.pos.z, Math.max(prevFeet, player.pos.y));
+  if (player.pos.y <= g + 0.012 && player.vel.y <= 0) {
+    if (player.wasAir && player.vel.y < -3.4) {
+      player.landKick = Math.min(0.16, -player.vel.y * 0.014);
+      player.shake = Math.min(0.9, -player.vel.y * 0.055);
+      SFX.step(g > 0.05);
+    }
+    player.pos.y = g;
+    player.vel.y = 0;
+    player.onGround = true;
+    player.wasAir = false;
+  } else {
+    player.onGround = false;
+    player.wasAir = true;
+  }
+
+  player.eye = damp(player.eye, player.crouched ? EYE_CROUCH : EYE_STAND, 12, dt);
+  player.height = damp(player.height, player.crouched ? H_CROUCH : H_STAND, 12, dt);
+  const hSpeed = Math.hypot(player.vel.x, player.vel.z);
+  player.speed = hSpeed;
+  player.strafe = moving ? ix : 0;
+  if (player.onGround && hSpeed > 0.4) {
+    player.stepDist += hSpeed * dt;
+    const stride = player.sprint ? 1.85 : (player.crouched ? 2.6 : 2.15);
+    if (player.stepDist > stride) {
+      player.stepDist = 0;
+      SFX.step(g > 0.05);
+    }
+    player.bobPhase += hSpeed * dt * (player.sprint ? 1.6 : 1.25);
+  }
+
+  GAME.recoilPitch = damp(GAME.recoilPitch, 0, 6.2, dt);
+  GAME.recoilYaw = damp(GAME.recoilYaw, 0, 5.4, dt);
+  player.shake = damp(player.shake, 0, 7, dt);
+  player.landKick = damp(player.landKick, 0, 8, dt);
+  player.roll = damp(player.roll, -player.strafe * 0.012 * (1 - adsFactor * 0.7), 8, dt);
+
+  const bobAmp = clamp(hSpeed / 5.4, 0, 1.35) * (1 - adsFactor * 0.72) * (player.onGround ? 1 : 0.2);
+  const bob = Math.sin(player.bobPhase * 2) * 0.013 * bobAmp;
+  const side = Math.cos(player.bobPhase) * 0.006 * bobAmp;
+  camera.position.set(player.pos.x + side, player.pos.y + player.eye + bob - player.landKick, player.pos.z);
+  const shX = Math.sin(time * 63.0) * player.shake * 0.011;
+  const shY = Math.cos(time * 49.0) * player.shake * 0.009;
+  camera.rotation.set(player.pitch + GAME.recoilPitch + shY, player.yaw + GAME.recoilYaw + shX, player.roll);
+
+  const targetFov = 72 + (player.sprint ? 7 : 0) - adsFactor * 20;
+  camera.fov = damp(camera.fov, targetFov, 9, dt);
+  camera.updateProjectionMatrix();
+
+  _fwd.set(0, 0, -1).applyQuaternion(camera.quaternion);
+  _right.set(1, 0, 0).applyQuaternion(camera.quaternion);
+  _up.set(0, 1, 0).applyQuaternion(camera.quaternion);
+  flashLight.position.copy(camera.position).addScaledVector(_right, 0.17).addScaledVector(_up, -0.11);
+  flashLight.target.position.copy(camera.position).addScaledVector(_fwd, 26).addScaledVector(_right, 0.2);
+  flashLight.intensity = damp(flashLight.intensity, flashLightTarget ? 120 : 0, 13, dt);
+  GUN.lens.emissiveIntensity = damp(GUN.lens.emissiveIntensity, flashLightTarget ? 2.8 : 0, 13, dt);
+}
+
+/* =========================================================================
+   WEAPON ANIMATION
+   ========================================================================= */
+function updateWeapon(dt, time) {
+  const ads = GAME.ads;
+  GAME.kickZ = damp(GAME.kickZ, 0, 17, dt);
+  GAME.kickY = damp(GAME.kickY, 0, 17, dt);
+  GAME.kickRot = damp(GAME.kickRot, 0, 16, dt);
+  GAME.swayX = damp(GAME.swayX, 0, 9, dt);
+  GAME.swayY = damp(GAME.swayY, 0, 9, dt);
+  GAME.boltKick = damp(GAME.boltKick, 0, 22, dt);
+
+  const reloadP = GAME.reloading ? clamp(GAME.reloadT / GAME.reloadDur, 0, 1) : 0;
+  const reloadAnim = GAME.reloading ? Math.sin(Math.PI * reloadP) : 0;
+  let insp = 0;
+  if (GAME.inspectT > 0) insp = Math.sin(Math.PI * (1 - GAME.inspectT / GAME.inspectDur));
+
+  const hipX = 0.168, hipY = -0.148, hipZ = -0.305;
+  const adsX = 0.0, adsY = -0.094, adsZ = -0.252;
+  let tx = lerp(hipX, adsX, ads);
+  let ty = lerp(hipY, adsY, ads);
+  let tz = lerp(hipZ, adsZ, ads);
+
+  const bobAmp = clamp(player.speed / 5.2, 0, 1.4) * (1 - ads * 0.82) * (player.onGround ? 1 : 0.25);
+  const bx = Math.sin(player.bobPhase) * 0.0075 * bobAmp;
+  const by = Math.abs(Math.cos(player.bobPhase)) * 0.0065 * bobAmp;
+  tx += bx + GAME.swayX * 0.35;
+  ty += by - GAME.swayY * 0.35;
+  tx += Math.sin(time * 1.35) * 0.0018 * (1 - ads);
+  ty += Math.cos(time * 1.05) * 0.0014 * (1 - ads);
+
+  if (player.sprint) {
+    tx += 0.035; ty -= 0.105; tz += 0.045;
