+  if (worldFlashT > 0) {
+    worldFlashT -= dt;
+    const k = clamp(worldFlashT / 0.05, 0, 1);
+    worldFlash.material.opacity = k;
+    worldFlash.scale.setScalar(lerp(0.28, 0.7, k));
+    worldFlashLight.intensity = 24 * k;
+    if (worldFlashT <= 0) { worldFlash.visible = false; worldFlashLight.intensity = 0; }
+  } else {
+    worldFlashLight.intensity = damp(worldFlashLight.intensity, 0, 20, dt);
+  }
+}
+
+function frame() {
+  requestAnimationFrame(frame);
+  const dt = Math.min(0.05, clock.getDelta());
+  elapsed += dt;
+  skyUniforms.uTime.value = elapsed;
+
+  GAME.ads = damp(GAME.ads, (GAME.adsHeld && !GAME.reloading && !player.sprint) ? 1 : 0, 11, dt);
+  if (GAME.started && !GAME.paused) {
+    updatePlayer(dt, elapsed);
+    updateReload(dt);
+    updateFiring(dt);
+    updateWeapon(dt, elapsed);
+    updateHud();
+  } else {
+    updateWeapon(dt, elapsed);
+  }
+  updateBullets(dt);
+  updateTargets(dt);
+  updateEffects(dt);
+  drawCompass();
+  updateDebug(dt);
+
+  renderer.clear();
+  renderer.render(scene, camera);
+  renderer.clearDepth();
+  renderer.render(weaponScene, weaponCamera);
+}
+
+camera.position.set(player.pos.x, player.pos.y + player.eye, player.pos.z);
+camera.rotation.set(player.pitch, player.yaw, 0);
+updateHud();
+requestAnimationFrame(frame);
+
+requestAnimationFrame(() => {
+  $('#loadbar').style.width = '100%';
+  $('#loadpct').textContent = '100%';
+  setTimeout(() => $('#loading').classList.add('hidden'), 320);
+});
+
+/* =========================================================================
+   AUTOMATION / DEBUG API
+   ========================================================================= */
+window.__GZ = {
+  start() {
+    startGame(false);
+    GAME.paused = false;
+    $('#pause').classList.add('hidden');
+    return this.state();
+  },
+  setView(yaw, pitch) { player.yaw = yaw; player.pitch = clamp(pitch, -1.4, 1.4); },
+  teleport(x, y, z) { player.pos.set(x, y, z); player.vel.set(0, 0, 0); },
+  ads(on) { GAME.adsHeld = !!on; },
+  fire(on = true) { GAME.firing = !!on; if (on) GAME.fireTimer = 0; },
+  reload: startReload,
+  inspect() { GAME.inspectT = GAME.inspectDur; },
+  light(on) { flashLightOn = !!on; flashLightTarget = on ? 1 : 0; },
+  crouch(on) { player.crouched = !!on; },
+  hideOverlays() {
+    $('#start').classList.add('hidden');
+    $('#pause').classList.add('hidden');
+    $('#loading').classList.add('hidden');
+    document.body.classList.add('playing');
+  },
+  state() {
+    return {
+      started: GAME.started, paused: GAME.paused, pos: player.pos.toArray(),
+      yaw: player.yaw, pitch: player.pitch, ammo: GAME.ammo, reserve: GAME.reserve,
+      score: GAME.score, reloading: GAME.reloading, targets: TARGETS.length,
+      errors: window.__errors.slice(),
+    };
+  },
+  scene, camera, player, game: GAME, targets: TARGETS,
+};
+</script>
+</body>
