/* extruded side-profile solid (profile in z,y; extruded across x) */
function wprofile(parent, pts, width, mat, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, bevel = 0.004) {
  const shape = new THREE.Shape();
  shape.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) shape.lineTo(pts[i][0], pts[i][1]);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: width, bevelEnabled: bevel > 0, bevelSize: bevel, bevelThickness: bevel, bevelSegments: 2, steps: 1,
  });
  geo.translate(0, 0, -width / 2);
  geo.rotateY(-Math.PI / 2);
  geo.computeVertexNormals();
  return wmesh(parent, geo, mat, x, y, z, rx, ry, rz);
}
